WITH unpacked AS (SELECT id, status_code, payload_json, context['version'] AS version, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['trace'] AS trace, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs) SELECT id, status_code, payload_json, version, retry_count, trace, trace_or_default, NTILE(4) OVER (ORDER BY status_code DESC, id) status_code_bucket, SUM(status_code) OVER (ORDER BY retry_count, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_status_code FROM unpacked
